from typing import List


def main():
    nums = [int(x) for x in input().split()]

    if si(nums):
        print('YES')
    else:
        print('NO')


def si(nums: List[int]) -> bool:
    a, b, c = nums
    a *= 10 ** 8
    b *= 10 ** 8
    c *= 10 ** 8

    if int(math.sqrt(a)) + int(math.sqrt(b)) < int(math.sqrt(c)):
        return True
    else:
        return False


